namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Room { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6–10 uppercase letters or digits.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    Task<List<Department>> GetDepartmentsAsync();
    Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null);
    Task<List<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseByIdAsync(int id);
    Task<Department?> GetDepartmentByIdAsync(int id);
    Task<Instructor?> GetInstructorByIdAsync(int id);
    Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Pure and applied mathematics including statistics." },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events and civilizations." },
    ];

    private static readonly List<Instructor> Instructors =
    [
        new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor of Computer Science", Email = "alovelace@university.edu", Bio = "Dr. Lovelace specializes in algorithm design and programming language theory. She has published over 40 peer-reviewed papers and received the Distinguished Teaching Award in 2024." },
        new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor of Computer Science", Email = "aturing@university.edu", Bio = "Dr. Turing's research focuses on artificial intelligence, computational complexity, and machine learning. He leads the university's AI Research Lab." },
        new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor of Mathematics", Email = "enoether@university.edu", Bio = "Dr. Noether is a leading researcher in abstract algebra and theoretical physics. She has been awarded multiple grants for her work in symmetry and conservation laws." },
        new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Professor of Physics", Email = "rfeynman@university.edu", Bio = "Dr. Feynman is renowned for his engaging lecture style and contributions to quantum mechanics and particle physics. Author of several popular science books." },
        new() { Id = 5, Name = "Dr. Maya Angelou", Title = "Professor of English", Email = "mangelou@university.edu", Bio = "Dr. Angelou brings 20 years of literary scholarship to the classroom. She specializes in American literature, creative writing, and poetry." },
        new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor of History", Email = "hzinn@university.edu", Bio = "Dr. Zinn focuses on social movements, labor history, and civil rights in American history. He emphasizes primary source analysis in his teaching." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and object-oriented programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Science Hall 305", IsFeatured = true, DepartmentId = 1, InstructorId = 2 },
        new() { Id = 3, Code = "CS 301", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Science Hall 401", IsFeatured = false, DepartmentId = 1, InstructorId = 2 },
        new() { Id = 4, Code = "CS 310", Title = "Software Engineering", Description = "Software development methodologies, requirements analysis, system design, testing, and project management. Includes a semester-long team project.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Science Hall 202", IsFeatured = false, DepartmentId = 1, InstructorId = 1 },
        new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 110", IsFeatured = true, DepartmentId = 2, InstructorId = 3 },
        new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Building 215", IsFeatured = false, DepartmentId = 2, InstructorId = 3 },
        new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Math Building 110", IsFeatured = false, DepartmentId = 2, InstructorId = 3 },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes a weekly lab session. Co-requisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM, Lab: Fri 1:00–3:00 PM", Room = "Physics Lab 100", IsFeatured = true, DepartmentId = 3, InstructorId = 4 },
        new() { Id = 9, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Includes a weekly lab session.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM, Lab: Thu 2:00–4:00 PM", Room = "Physics Lab 100", IsFeatured = false, DepartmentId = 3, InstructorId = 4 },
        new() { Id = 10, Code = "ENG 101", Title = "College Composition", Description = "Development of academic writing skills including argumentation, research, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Humanities 105", IsFeatured = false, DepartmentId = 4, InstructorId = 5 },
        new() { Id = 11, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Humanities 210", IsFeatured = true, DepartmentId = 4, InstructorId = 5 },
        new() { Id = 12, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient times to 1500 CE. Emphasis on cultural exchange and comparative analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Liberal Arts 300", IsFeatured = false, DepartmentId = 5, InstructorId = 6 },
        new() { Id = 13, Code = "HIST 250", Title = "Modern American History", Description = "United States history from the Civil War to the present, focusing on social movements, political change, and cultural transformation.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Liberal Arts 305", IsFeatured = true, DepartmentId = 5, InstructorId = 6 },
    ];

    public Task<List<Department>> GetDepartmentsAsync() =>
        Task.FromResult(Departments.ToList());

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return Task.FromResult(query.OrderBy(c => c.Code).ToList());
    }

    public Task<List<Course>> GetFeaturedCoursesAsync() =>
        Task.FromResult(Courses.Where(c => c.IsFeatured).ToList());

    public Task<Course?> GetCourseByIdAsync(int id) =>
        Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));

    public Task<Department?> GetDepartmentByIdAsync(int id) =>
        Task.FromResult(Departments.FirstOrDefault(d => d.Id == id));

    public Task<Instructor?> GetInstructorByIdAsync(int id) =>
        Task.FromResult(Instructors.FirstOrDefault(i => i.Id == id));

    public Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request) =>
        Task.FromResult(true);
}

