@using CourseCatalog.Models

<div class="card h-100">
    <div class="card-body">
        <h5 class="card-title">@Course.Code — @Course.Title</h5>
        <p class="card-text text-muted mb-2">@Course.Credits credits · @Course.Schedule</p>
        <p class="card-text">@Truncate(Course.Description, 120)</p>
    </div>
    <div class="card-footer bg-transparent">
        <a href="courses/@Course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using CourseCatalog.Models

<div class="list-group">
    @foreach (var dept in Departments)
    {
        <a href="courses?departmentId=@dept.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
            <div>
                <strong>@dept.Abbreviation</strong> — @dept.Name
            </div>
            <span class="badge bg-primary rounded-pill">@dept.Abbreviation</span>
        </a>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = [];
}

@using CourseCatalog.Models

<div class="card">
    <div class="card-body">
        <h5 class="card-title">@Instructor.Name</h5>
        <h6 class="card-subtitle mb-2 text-muted">@Instructor.Title</h6>
        <p class="card-text">@Instructor.Bio</p>
        <a href="mailto:@Instructor.Email" class="card-link">@Instructor.Email</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Instructor Instructor { get; set; } = default!;
}

@using CourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <input type="text" class="form-control" placeholder="Search courses…"
               value="@SearchTerm" @oninput="OnSearchInput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" value="@DepartmentId" @onchange="OnDepartmentChange">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public int DepartmentId { get; set; }
    [Parameter] public List<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> DepartmentIdChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        await SearchTermChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var id))
            await DepartmentIdChanged.InvokeAsync(id);
    }
}

