@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters SearchTerm="@_searchTerm"
              DepartmentId="@_departmentId"
              Departments="_departments"
              SearchTermChanged="OnSearchChanged"
              DepartmentIdChanged="OnDepartmentChanged" />

<CourseList Courses="_filteredCourses" />

@code {
    private List<Department> _departments = [];
    private List<Course> _filteredCourses = [];
    private string _searchTerm = string.Empty;
    private int _departmentId;

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _departments = await CatalogService.GetDepartmentsAsync();

        if (DepartmentId.HasValue)
            _departmentId = DepartmentId.Value;

        await LoadCoursesAsync();
    }

    private async Task OnSearchChanged(string term)
    {
        _searchTerm = term;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentChanged(int id)
    {
        _departmentId = id;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        _filteredCourses = await CatalogService.GetCoursesAsync(_searchTerm, _departmentId > 0 ? _departmentId : null);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course") — University Course Catalog</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Code — @_course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@_course.Description</p>

            <h4 class="mt-4">Schedule &amp; Location</h4>
            <table class="table table-bordered w-auto">
                <tbody>
                    <tr><th>Schedule</th><td>@_course.Schedule</td></tr>
                    <tr><th>Room</th><td>@_course.Room</td></tr>
                    <tr><th>Credits</th><td>@_course.Credits</td></tr>
                </tbody>
            </table>

            @if (_department is not null)
            {
                <p><strong>Department:</strong> @_department.Name</p>
            }

            <a href="enroll" class="btn btn-primary mt-2">Enroll in This Course</a>
        </div>

        <div class="col-md-4">
            @if (_instructor is not null)
            {
                <h4>Instructor</h4>
                <InstructorBio Instructor="_instructor" />
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;
    private Department? _department;
    private Instructor? _instructor;

    protected override async Task OnInitializedAsync()
    {
        _course = await CatalogService.GetCourseByIdAsync(Id);
        if (_course is not null)
        {
            _department = await CatalogService.GetDepartmentByIdAsync(_course.DepartmentId);
            _instructor = await CatalogService.GetInstructorByIdAsync(_course.InstructorId);
        }
    }
}

